CAT = "afspNewDed"; SEG = "NDD"
# AFTR outline 1.9 to 1.14: itemized deduction changes (IRC 68, 163(h), 165(d) and (h), 164(b)(7)),
# Schedule 1-A deductions (tips, overtime, car loan interest, seniors; FS-2025-03), charitable changes
# (IRC 170(b)(1)(I), 170(p)), 529 changes, Trump accounts (Notice 2025-68), HSA changes (Notice 2026-5).
# Tax year 2026. Computed keys asserted.
_lim = 74000 * 2 // 37; assert _lim == 4000
_salt = 40400 - 30 * (545000 - 505000) // 100; assert _salt == 28400
_salt_floor = max(10000, 40400 - 30 * (700000 - 505000) // 100); assert _salt_floor == 10000
_gam1 = min(10000 * 90 // 100, 10000); assert _gam1 == 9000
_gam2 = min(8000 * 90 // 100, 5000); assert _gam2 == 5000
_cas = 20000 - 100 - 50000 // 10; assert _cas == 14900
_ot = 100 * (20 // 2); assert _ot == 1000
_sen = 2 * 6000; assert _sen == 12000
_char = min(2600, 2000); assert _char == 2000
_floor = 3000 - 100000 * 5 // 1000; assert _floor == 2500

Q = [
("A single filer has $74,000 of 2026 itemized deductions, and income above the 37% bracket start exceeds that. The new limitation reduces them by:",
 f"${_lim:,}", ["$7,400", "$2,960", "$1,480"],
 "IRC 68 as amended reduces itemized deductions by 2/37 of the lesser of the deductions or the income above the 37% bracket threshold. 2/37 x $74,000 = $4,000."),
("The overall limitation on itemized deductions that starts in 2026 affects taxpayers whose income reaches which bracket?",
 "37%", ["35%", "32%", "24%"],
 "The 2/37 reduction applies only to income above the start of the 37% bracket, which caps the tax value of itemized deductions at 35 cents a dollar (OBBBA section 70111)."),
("In 2026, a homeowner takes a home equity loan and uses it all to add a bedroom to the home. The interest is:",
 "Deductible as acquisition debt", ["Not deductible at all", "Deductible up to $100,000", "Deductible on Schedule C"],
 "Debt secured by the home and used to buy, build or substantially improve it is acquisition debt, whatever the loan is called (IRC 163(h)(3)). Interest on true home equity debt used for other purposes is not deductible."),
("Starting in 2026, qualified mortgage insurance premiums on acquisition debt for a main home are treated as:",
 "Qualified residence interest", ["A medical expense", "A real estate tax", "A personal expense"],
 "OBBBA section 70108 brought back IRC 163(h)(3)(E), so these premiums count as deductible mortgage interest on Schedule A, subject to an AGI phaseout."),
("For 2026, which personal casualty loss can be deducted by a taxpayer with no casualty gains?",
 "One from a state-declared disaster", ["One from a kitchen fire", "One from a car accident", "One from a burst pipe"],
 "IRC 165(h)(5) as amended allows personal casualty losses only when they come from a federally declared or state-declared disaster, unless the taxpayer has personal casualty gains."),
("A 2026 state-declared disaster caused a $20,000 personal casualty loss. The owner itemizes and has AGI of $50,000. The deductible loss is:",
 f"${_cas:,}", ["$15,000", "$19,900", "$20,000"],
 "The loss is cut by $100 per casualty and then by 10% of AGI: $20,000 - $100 - $5,000 = $14,900. It goes on Form 4684 and Schedule A."),
("An itemizer had $10,000 of gambling winnings and $10,000 of gambling losses in 2026. The deductible losses are:",
 f"${_gam1:,}", ["$10,000", "$1,000", "$0"],
 "From 2026, IRC 165(d) allows only 90% of wagering losses, still limited to winnings. 90% of $10,000 is $9,000, so $1,000 of the winnings stays taxable."),
("For 2026, Dee won $5,000 and lost $8,000 gambling, and she itemizes. Her deductible losses are:",
 f"${_gam2:,}", ["$7,200", "$8,000", "$4,500"],
 "90% of the $8,000 losses is $7,200, but wagering losses are deductible only up to wagering gains, so the deduction stops at $5,000."),
("A single filer has 2026 MAGI of $545,000. Her state and local tax deduction limit is:",
 f"${_salt:,}", ["$40,400", "$10,000", "$12,000"],
 "The 2026 limit of $40,400 is reduced by 30% of MAGI over $505,000 (IRC 164(b)(7)). $40,000 over x 30% = $12,000, leaving $28,400."),
("A joint return for 2026 shows MAGI of $700,000. The state and local tax deduction is capped at:",
 f"${_salt_floor:,}", ["$40,400", "$20,200", "$0"],
 "The phasedown can never take the limit below $10,000. At this MAGI the 30% reduction would erase the $40,400 cap, so the $10,000 floor applies."),
("For 2026, what is the state and local tax deduction limit for married filing separately, before any phasedown?",
 "$20,200", ["$40,400", "$10,000", "$5,000"],
 "A married person filing separately gets half the $40,400 limit, $20,200 (IRC 164(b)(6) and (7)), and the 30% phasedown starts at half the $505,000 threshold."),
("Which of these counts as qualified tips for the 2026 tip deduction?",
 "Tips shared from a tip pool", ["Mandatory service charges", "Hourly wages for waiting tables", "Tips in a non-tipping job"],
 "Qualified tips are voluntary cash or charged tips from customers or through tip sharing, in an occupation the IRS lists as customarily tipped (FS-2025-03). A required service charge is not voluntary."),
("For a self-employed hair stylist, the 2026 deduction for qualified tips cannot exceed:",
 "Net income from that business", ["Gross tips received", "Half of all tips", "Wages from another job"],
 "The IRS fact sheet says a self-employed individual's tip deduction may not exceed net income, figured without this deduction, from the trade or business where the tips were earned. The $25,000 cap also applies."),
("Where does a taxpayer claim the new tip, overtime, car loan interest and senior deductions?",
 "Schedule 1-A", ["Schedule A", "Schedule C", "Schedule 1, Part I"],
 "These four deductions are figured on Schedule 1-A, Additional Deductions (FS-2025-03). They are taken whether or not the taxpayer itemizes on Schedule A."),
("Jo earns $20 an hour and worked 100 FLSA overtime hours at time-and-a-half in 2026. Her qualified overtime compensation is:",
 f"${_ot:,}", ["$3,000", "$2,000", "$1,500"],
 "Only the premium above the regular rate counts, the half in time-and-a-half (IRS overtime FAQs). 100 hours x $10 = $1,000; the $2,000 regular-rate part is not qualified."),
("Overtime pay that only a union contract requires, for a worker the FLSA does not cover, is:",
 "Not qualified overtime", ["Qualified up to $12,500", "Qualified at the half rate", "Qualified if on Form W-2"],
 "Qualified overtime must be required by section 7 of the FLSA. If the worker is not FLSA overtime-eligible, pay required by other laws or a collective bargaining agreement does not qualify (IRS overtime FAQs)."),
("Raul is married and receives qualified overtime pay. To claim the 2026 overtime deduction, he must:",
 "File a joint return", ["Itemize his deductions", "File separately", "Report it on Schedule C"],
 "A married taxpayer must file jointly to claim the deduction and must include a work-eligible SSN (IRS overtime FAQs). It is available whether or not he itemizes."),
("Which 2026 purchase can produce interest for the car loan interest deduction?",
 "New U.S.-assembled SUV", ["Used U.S.-assembled sedan", "Leased U.S.-assembled truck", "New SUV for business use"],
 "The loan must be for a new personal-use vehicle under 14,000 pounds with final assembly in the United States, secured by a lien (FS-2025-03). Used cars, leases and business vehicles do not qualify."),
("To claim the car loan interest deduction, the return must include the vehicle's:",
 "Identification number (VIN)", ["Window sticker price", "Odometer reading", "State title number"],
 "The taxpayer must report the VIN of the qualified vehicle on the return for every year the deduction is claimed (FS-2025-03)."),
("Interest on a qualifying 2025 car loan that is refinanced in 2026 is:",
 "Generally still eligible", ["No longer deductible", "Deductible as business interest", "Deductible only if itemizing"],
 "IRS guidance says that if a qualifying vehicle loan is later refinanced, interest on the refinanced amount is generally eligible. The deduction is taken whether or not the taxpayer itemizes."),
("A married couple, both 68, file jointly for 2026 with MAGI of $90,000. Their enhanced senior deduction is:",
 f"${_sen:,}", ["$6,000", "$3,300", "$15,300"],
 "The deduction is $6,000 per qualifying spouse and starts to phase out above $150,000 of MAGI on a joint return (FS-2025-03). It is on top of the $1,650 additional standard deduction each."),
("A taxpayer born on December 30, 1961 files a 2026 return. For the $6,000 senior deduction, she is:",
 "Eligible for 2026", ["Eligible from 2027", "Eligible at 66", "Eligible only if retired"],
 "She must reach 65 by the last day of the tax year. She turns 65 on December 30, 2026, so she qualifies for 2026; the deduction runs from 2025 through 2028."),
("A married couple who take the 2026 standard deduction gave $2,600 in cash to their church. Their charitable deduction is:",
 f"${_char:,}", ["$2,600", "$1,000", "$1,300"],
 "From 2026, non-itemizers may deduct cash gifts to qualifying charities up to $1,000, or $2,000 on a joint return (IRC 170(p)). The other $600 gives no deduction."),
("Which 2026 gift counts toward the charitable deduction for taxpayers who do not itemize?",
 "Cash to a food bank", ["Clothing to a thrift shop", "Stock to a university", "Cash to a donor-advised fund"],
 "Only cash gifts to qualifying charities count. Gifts of property and gifts to donor-advised funds or supporting organizations do not (IRS Working Families Tax Cuts page)."),
("An itemizer with a $100,000 contribution base gives $3,000 cash to charity in 2026. Before percentage limits, the deductible amount is:",
 f"${_floor:,}", ["$3,000", "$2,700", "$2,000"],
 "From 2026 itemized charitable gifts count only above 0.5% of the contribution base (IRC 170(b)(1)(I)). 0.5% of $100,000 is $500, so $2,500 is deductible."),
("For 2026, tax-free 529 plan distributions for K-12 tuition are limited per beneficiary to:",
 "$20,000 a year", ["$10,000 a year", "$19,000 a year", "$5,250 a year"],
 "OBBBA section 70413 doubled the annual per-beneficiary limit for elementary and secondary tuition from $10,000 to $20,000, starting with 2026 distributions (IRC 529(e)(3))."),
("Under the 2025 law, qualified 529 expenses now include:",
 "Postsecondary credentialing costs", ["Off-campus parking permits", "Student health insurance", "Dorm room furnishings"],
 "OBBBA section 70414 adds qualified postsecondary credentialing expenses, such as costs of recognized credential programs, to the definition of qualified higher education expenses."),
("Which child can receive the $1,000 Trump account pilot program contribution?",
 "U.S. citizen born in March 2026", ["U.S. citizen born in 2024", "Any child under age 18", "U.S. citizen born in 2029"],
 "The pilot contribution is for a U.S. citizen child born after December 31, 2024 and before January 1, 2029 who has an SSN (Notice 2025-68). The election is made on Form 4547."),
("Parents put $2,000 into their child's Trump account in 2026. On their own return, they can deduct:",
 "Nothing", ["$2,000", "$1,000", "Up to $5,000"],
 "Contributions from individuals are not deductible (Notice 2025-68). They are limited to $5,000 a year in total with employer contributions, and contributions could not start before July 4, 2026."),
("An employer puts $2,500 into the Trump account of an employee's child in 2026. For the employee, the amount is:",
 "Excluded from income", ["Taxable wages", "Taxable above $1,000", "Deductible by the employee"],
 "Employer contributions under a section 128 Trump account contribution program are excluded from the employee's income up to $2,500 a year (Notice 2025-68)."),
("Starting in 2026, which Exchange plan is treated as a high deductible plan for HSA purposes?",
 "Bronze plan", ["Gold plan", "Silver plan", "Platinum plan"],
 "OBBBA section 71307 treats bronze and catastrophic plans as HDHPs from January 1, 2026, so more people can contribute to an HSA (Notice 2026-5)."),
("From 2026, an HSA owner may also have a direct primary care arrangement if the monthly fee for one person is at most:",
 "$150", ["$300", "$100", "$250"],
 "Notice 2026-5 says an arrangement is not a direct primary care service arrangement if fees exceed $150 a month, or $300 for one covering more than one person. HSA funds can pay those fees."),
]
